import{_ as e,c,o as d,aN as a}from"./chunks/framework.wz1796_d.js";const h=JSON.parse('{"title":"蓝奏云无法访问","description":"蓝奏云无法访问","frontmatter":{"title":"蓝奏云无法访问","description":"蓝奏云无法访问"},"headers":[],"relativePath":"info/lanzou.md","filePath":"info/lanzou.md"}'),t={name:"info/lanzou.md"};function p(l,o,i,s,n,r){return d(),c("div",null,[...o[0]||(o[0]=[a('<h1 id="蓝奏云无法访问的问题" tabindex="-1">蓝奏云无法访问的问题 <a class="header-anchor" href="#蓝奏云无法访问的问题" aria-label="Permalink to &quot;蓝奏云无法访问的问题&quot;">​</a></h1><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><p>由于运营商的 <code>DNS 污染</code>或 <code>解析异常</code> 等原因，部分 <code>地区</code> 或 <code>浏览器</code> 可能无法正常访问蓝奏云分享链接，提示 <code>文件不存在，或已删除</code> 或 <code>无法访问此页面</code> 或 其他访问失败的情况</p><p>现给出一些解决方案，可按需查看使用</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>如果你能 <code>正常访问链接</code> 和 <code>下载文件</code>，就不需要往下看了</p></div><h2 id="链接格式分享" tabindex="-1">链接格式分享 <a class="header-anchor" href="#链接格式分享" aria-label="Permalink to &quot;链接格式分享&quot;">​</a></h2><p>蓝奏云分享链接的格式一般为 <code>https://</code> + [<code>www</code> 或 <code>自定义域名</code>] + <code>蓝奏云域名</code> + <code>分享id</code></p><p>例如分享链接 <code>https://dishuo.lanzouw.com/b0eylud6j</code></p><p>其中的自定义域名为 <code>dishuo</code></p><p>蓝奏云域名为 <code>lanzouw.com</code></p><p>分享id为 <code>b0eylud6j</code></p><h2 id="方式1-修改蓝奏云域名-推荐" tabindex="-1">方式1：修改蓝奏云域名 (推荐) <a class="header-anchor" href="#方式1-修改蓝奏云域名-推荐" aria-label="Permalink to &quot;方式1：修改蓝奏云域名 (推荐)&quot;">​</a></h2><p>由于蓝奏云有很多域名，那么如果某一个分享链接无法打开，只需要修改其中的域名即可，只要 <code>分享id</code> 一样，所访问的文件就是同一个</p><p>而蓝奏云的域名绝大部分都为 <code>lanzou</code> + <code>一个字母</code> + <code>.com</code> 这样的格式，那么只需要修改 <code>lanzou</code> 后面的字母即可，可以修改成</p><p><code>d f h i j k l m o p q t u v w x y</code> 任意一个后尝试访问</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>修改为 <code>d c z</code> 可以在夸克浏览器打开</p><p>并非所有字母都可访问，<code>a b e g n s</code> 打不开的，<code>r</code> 可以打开，但不建议使用</p></div><h2 id="方式2-修改dns地址" tabindex="-1">方式2：修改DNS地址 <a class="header-anchor" href="#方式2-修改dns地址" aria-label="Permalink to &quot;方式2：修改DNS地址&quot;">​</a></h2><p>如果你知道如何修改DNS地址，那么可修改后尝试访问(并非100%解决)，无须修改链接</p><p>下面是一些常见的公共DNS信息</p><p>阿里DNS：主选 <code>223.5.5.5</code>备选 <code>223.6.6.6</code></p><p>腾讯DNS：主选 <code>119.29.29.29</code>备选 <code>182.254.116.116</code></p><p>百度DNS：主选 <code>180.76.76.76</code>备选 <code>180.76.76.216</code></p><p>字节跳动DNS：主选 <code>180.184.1.1</code>备选 <code>180.184.2.2</code></p><p>360安全DNS：主选 <code>101.226.4.6</code>备选 <code>218.30.118.6</code></p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>部分网络修改DNS后会造成没有网络，常见在 <code>校园网络</code> 或 <code>公司网络</code></p><p>如修改后无网络，请恢复默认后，并且尝试使用第1种方式</p></div>',25)])])}const m=e(t,[["render",p]]);export{h as __pageData,m as default};
